import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

function readJsonFile(filePath) {
  return JSON.parse(readFileSync(filePath, 'utf-8'));
}

function buildGeneratedModule(source) {
  return `// This file is generated by scripts/generate-browser-data.js
// Do not edit manually.

export const hub = ${JSON.stringify(source.hub, null, 2)};
export const locations = ${JSON.stringify(source.locations, null, 2)};
export const actSummary = ${JSON.stringify(source.actSummary, null, 2)};
export const items = ${JSON.stringify(source.items, null, 2)};
export const monsters = ${JSON.stringify(source.monsters, null, 2)};
export const shops = ${JSON.stringify(source.shops, null, 2)};
export const shopConfig = ${JSON.stringify(source.shopConfig, null, 2)};
export const itemNames = ${JSON.stringify(source.itemNames, null, 2)};
`;
}

export async function generateBrowserData() {
  const rootDir = process.cwd();
  const outputDir = path.join(rootDir, 'src', 'browser', 'generated');
  const outputFile = path.join(outputDir, 'browserData.generated.js');
  const locationsData = readJsonFile(path.join(rootDir, 'data', 'locations.json'));
  const shopsData = readJsonFile(path.join(rootDir, 'data', 'shops.json'));
  const itemsModule = await import(pathToFileURL(path.join(rootDir, 'dist', 'data', 'items.js')).href);
  const monstersModule = await import(pathToFileURL(path.join(rootDir, 'dist', 'data', 'monsters.js')).href);
  const items = itemsModule.getSampleItems();
  const monsters = monstersModule.getSampleMonsters();
  const itemNames = Object.fromEntries(
    Object.values(items).map(item => [item.id, item.name])
  );

  mkdirSync(outputDir, { recursive: true });
  writeFileSync(outputFile, buildGeneratedModule({
    hub: locationsData.hub,
    locations: locationsData.locations,
    actSummary: locationsData.actSummary,
    items,
    monsters,
    shops: shopsData.shops,
    shopConfig: shopsData.shopConfig,
    itemNames
  }), 'utf-8');

  return outputFile;
}

const directRunEntry = pathToFileURL(process.argv[1] ?? '').href;
if (import.meta.url === directRunEntry) {
  const outputFile = await generateBrowserData();
  console.log(`[browser-data] generated ${path.relative(process.cwd(), outputFile)}`);
}
